contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: sender (from whose balance tokens are moved), recipient, spenderAllowanceSetter (who will approve this contract), amount
    function run(address sender, address recipient, address spenderAllowanceSetter, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0), "nonzero addrs");
        // record total supply before
        uint256 tBefore = c.totalSupply();

        // Record balances and allowance before. These are view calls allowed inside run.
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 allowanceBefore = c.allowance(sender, address(this));

        // We need to ensure this contract is allowed to spend `amount` from sender. The only way through public surface is approve called by msg.sender (this contract) on c, but approve sets allowance(owner=msg.sender). So to set allowance of sender->this, the sender must call approve; we cannot make an external account call here. However, c has increaseAllowance/decreaseAllowance which also act for msg.sender. So we cannot change allowance of another account.
        // But transferFrom will only succeed if allowance >= amount. We'll try the call and observe revert flag.

        bool reverted;
        try c.transferFrom(sender, recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-state
        uint256 tAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(sender, address(this));

        // If transferFrom succeeded (didn't revert), then totalSupply must be unchanged,
        // sender balance decreased by exactly amount and recipient increased by exactly amount,
        // and allowance decreased by amount (unless allowanceBefore was max uint and implementation doesn't subtract beyond that).
        // If it reverted, we only require totalSupply unchanged.

        if (!reverted) {
            // avoid underflow in assert by using >= comparisons
            assert(tAfter == tBefore &&
                   balSenderBefore >= amount &&
                   balSenderAfter + amount == balSenderBefore &&
                   balRecipientAfter == balRecipientBefore + amount &&
                   allowanceBefore >= amount &&
                   allowanceAfter + amount == allowanceBefore);
        } else {
            assert(tAfter == tBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Inputs: sender, recipient, amount, useTransferFrom flag to choose which call to invoke
    function run(address sender, address recipient, uint256 amount, bool useTransferFrom) public payable {
        require(sender != address(0) && recipient != address(0) && sender != recipient, "nonzero distinct addrs");

        // observe before-state
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);

        // perform the chosen transfer; capture whether it reverted
        bool reverted;
        if (useTransferFrom) {
            // transferFrom may revert; call at top-level
            try c.transferFrom(sender, recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // transfer from msg.sender (which is this contract). This will likely revert unless this contract holds tokens.
            try c.transfer(recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe after-state
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);

        // General invariant: totalSupply never changes, and if the transfer succeeded then the sum of the two balances is conserved
        assert(totalAfter == totalBefore && (reverted || (balSenderBefore + balRecipientBefore == balSenderAfter + balRecipientAfter)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: sender, recipient, amount, callTransferFrom chooses which function to invoke
    function run(address sender, address recipient, uint256 amount, bool callTransferFrom) public payable {
        require(sender != address(0) && recipient != address(0), "nonzero addrs");

        // observe before-state via public getters
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 allowanceBefore = c.allowance(sender, address(this));

        // perform the chosen call as a single top-level statement and capture whether it reverted
        bool reverted;
        if (callTransferFrom) {
            try c.transferFrom(sender, recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            try c.transfer(recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }

        // observe after-state
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 allowanceAfter = c.allowance(sender, address(this));

        // If the call did not revert then totalSupply must be unchanged.
        // Also the sender's balance cannot have decreased by more than amount, and recipient's balance cannot have increased by more than amount.
        // For transferFrom, allowance must not increase (it may decrease or remain same depending on implementation/ revert).
        assert((reverted) || (
            totalAfter == totalBefore
            && balSenderBefore >= balSenderAfter
            && balSenderBefore - balSenderAfter <= amount
            && balRecipientAfter >= balRecipientBefore
            && balRecipientAfter - balRecipientBefore <= amount
            && (!callTransferFrom || allowanceAfter <= allowanceBefore)
        ));
    }

    receive() external payable {}
}

