        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));
        uint256 balRecipientBefore = c.balanceOf(recipient);

        // Perform the transfer as a single top-level statement and capture whether it reverted
        bool reverted;
        try c.transfer(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-state
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balRecipientAfter = c.balanceOf(recipient);

        // If the transfer did not revert then totalSupply is unchanged and balances moved by exactly amount
        assert(reverted || (
            totalAfter == totalBefore
