contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry: test transfers where one party may be an allowed role
    // params: from and to addresses and amount; we will attempt to transfer from->to
    function run(address from, address to, uint256 amount) public payable {
        require(from != address(0) && to != address(0));
        // Read balances before
        uint256 beforeFrom = c.balanceOf(from);
        uint256 beforeTo = c.balanceOf(to);
        uint256 totalBefore = c.totalSupply();

        bool reverted;
        // perform transfer attempt as if msg.sender is this contract: use transferFrom if allowance set
        // We cannot change allowances of 'from' (we are this contract), so try calling c.transferFrom(from,to,amount)
        // It will likely revert unless allowance exists. We catch revert flag.
        try c.transferFrom(from, to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read balances after
        uint256 afterFrom = c.balanceOf(from);
        uint256 afterTo = c.balanceOf(to);
        uint256 totalAfter = c.totalSupply();

        // General rule (assert): If the call did NOT revert then
        // 1) totalSupply is unchanged
        // 2) recipient's balance is >= before recipient's balance (never decreased)
        // 3) sender's balance is <= before sender's balance (never increased)
        // This expresses conservation and monotonicity for a successful transfer
        assert(reverted || (totalAfter == totalBefore && afterTo >= beforeTo && afterFrom <= beforeFrom));
    }

    receive() external payable {}
}

