contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function: try transfers that are below minTxnAmount and involve allowed role
    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0), true);
        // Ensure amount is non-zero and less than minTxnAmount to hit the branch without reward
        uint256 minTxn = c.minTxnAmount();
        // require amount < minTxn to exercise branch without reward; if minTxn==0 skip
        require(minTxn > 0 && amount > 0 && amount < minTxn, true);

        // Make this contract the owner (constructor of c set owner to deployer, which was external);
        // We cannot change c's deployer here. But we can use only public surface: allowedRoles has no getter.
        // However transfers require either sender or recipient to be allowed role. The deploy-time owner may set roles via onlyOwner functions do not exist.
        // To satisfy role requirement, we attempt transferFrom where msg.sender is this contract: must rely on allowance and balances.
        // Instead, we will perform the transfer by calling c.transfer from this contract (msg.sender == InvMutTest).
        // To ensure role check passes, we observe that during construction of c the deployer got the initial tokens. The checker deploys a fresh c and passes it into this test's constructor — so this contract is NOT the original deployer and likely is not allowed. To create an allowed role, we try to call c.changeOwner and then set roles not available. Since we cannot access internal mapping, we instead assert a property that if a transfer call reverts due to role, then no state is changed; otherwise balances move by amount and txReward unchanged.

        // Read before-values
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 rewardSenderBefore = c.txReward(sender);
        uint256 rewardRecipientBefore = c.txReward(recipient);
        uint256 totalBefore = c.totalSupply();

        // Attempt transfer: we must call a function that changes state at top-level. Use try/catch to detect revert.
        bool reverted;
        try c.transfer{value: 0}(recipient, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 rewardSenderAfter = c.txReward(sender);
        uint256 rewardRecipientAfter = c.txReward(recipient);
        uint256 totalAfter = c.totalSupply();

        // General rule: if the attempted transfer reverted then balances and rewards and totalSupply are unchanged (from caller perspective);
        // otherwise, for a successful transfer the sum of sender+recipient balances decreases/increases exactly by amount (i.e., sender lost amount and recipient gained amount), and txReward for both did not increase because amount < minTxnAmount.
        assert(
            (reverted && balSenderAfter == balSenderBefore && balRecipientAfter == balRecipientBefore && rewardSenderAfter == rewardSenderBefore && rewardRecipientAfter == rewardRecipientBefore && totalAfter == totalBefore)
            ||
            (!reverted && balSenderBefore >= amount && balSenderAfter + balRecipientAfter == balSenderBefore + balRecipientBefore && balSenderAfter == balSenderBefore - amount && balRecipientAfter == balRecipientBefore + amount && rewardSenderAfter == rewardSenderBefore && rewardRecipientAfter == rewardRecipientBefore && totalAfter == totalBefore)
        );
    }

    receive() external payable {}
}

