        // Read after-values
        uint256 afterSenderBal = c.balanceOf(sender);
        uint256 afterRecipientBal = c.balanceOf(recipient);
        uint256 afterSenderReward = c.txReward(sender);
        uint256 afterRecipientReward = c.txReward(recipient);

        // General rule:
        // If the transfer succeeded (not reverted) AND neither sender nor recipient is in allowedRoles
        // (the contract enforces this and would revert otherwise), then the balances must have changed by exactly tAmount
        // (sender decreased by tAmount, recipient increased by tAmount) and txReward for both addresses must be unchanged.
        // We express "neither has allowed role" indirectly: if transfer succeeded and before/after balances changed
        // exactly by tAmount, then it must be the no-role path; enforce the invariant that when transfer succeeded and
        // balances moved as simple transfer, rewards did not change.

