            reverted || (
                afterSenderBal + tAmount == beforeSenderBal &&
                afterRecipientBal == beforeRecipientBal + tAmount &&
                afterSenderReward == beforeSenderReward &&
                afterRecipientReward == beforeRecipientReward
            )
        );
    }

