        // - if succeeded: allowance decreased by amount (but not below zero) and sum of sender+recipient balances preserved
        assert(
            totalAfter == totalBefore
            && ownerAfter == ownerBefore
            && (reverted
                ? (balSenderAfter == balSenderBefore && balRecAfter == balRecBefore && allowanceAfter == allowanceBefore)
                : (balSenderAfter + balRecAfter == balSenderBefore + balRecBefore && allowanceAfter + amount == allowanceBefore))
        );
    }

