contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // addrFrom: the sender of tokens
    // addrTo: the recipient of tokens
    // tAmount: the token amount to transfer (in token units, not scaled)
    // isSenderAllowed: whether sender should be granted the special allowed role (buy-role)
    // isRecipientAllowed: whether recipient should be granted the special allowed role (sell-role)
    // contractRewardBalance: amount of tokens to ensure the token contract holds to be able to pay rewards
    function run(address addrFrom, address addrTo, uint256 tAmount, bool isSenderAllowed, bool isRecipientAllowed, uint256 contractRewardBalance) public payable {
        require(addrFrom != address(0) && addrTo != address(0), "nonzero addrs");
        require(addrFrom != addrTo, "distinct addrs");

        // initial reads
        uint256 minTxn = c.minTxnAmount();
        uint256 rewardRate = c.rewardRate();
        uint256 percent = c.percent();

        // compute expected rewardAmount according to contract logic
        uint256 expectedReward = 0;
        if (tAmount >= minTxn) {
            expectedReward = (tAmount * rewardRate) / percent;
        }

        // set up: ensure this test contract has enough reflected tokens to transfer from addrFrom
        // We cannot mint or set balances externally except via public surface. However constructor of C minted all tokens to deployer (this test deployed C), so msg.sender of that mint was the deployer outside this test context. The test can use transfer to move tokens from this contract (which is owner of c) to addrFrom if needed.
        // Transfer some tokens from this test contract to addrFrom so addrFrom has balance to send.
        // Note: transfer is a state-changing call and must be top-level.
        // Ensure this contract (InvMutTest) has enough tokens: after deployment of C this contract is the deployer (per problem) and received initial supply. So we transfer a large amount to addrFrom and to the contract itself for reward pool.

        // Give addrFrom a large balance to cover tAmount
        c.transfer(addrFrom, 1000000 * (10 ** c.decimals()));

        // Ensure contract (c) holds enough tokens to pay rewards: transfer tokens into c from this contract
        // We cap the amount to a safe large value; if contractRewardBalance is zero it's fine.
        if (contractRewardBalance > 0) {
            // transfer tokens from this test contract to the token contract address
            c.transfer(address(c), contractRewardBalance);
        }

        // Now set allowed roles via changeOwner and then call into the private mapping isn't possible; but allowed roles are private with no setter. However _allowedRoles is private and there is no public setter. The contract's logic requires _allowedRoles[sender] or recipient true else transfer reverts. The constructor set owner to deployer and onlyOwner functions exist to set owner. But no function to set roles. Therefore to reach branches we rely on the fact that the constructor likely set _allowedRoles for some addresses — but this is unknown. To avoid relying on unknown roles, we restrict to the case where either sender or recipient is address(this) (the test contract), because we know transfers from this test contract are allowed by default by the contract's design: the initial mint put tokens into owner (the deployer) and our test contract deployed C and hence should be owner. The owner likely has no special allowed role either. To craft a general rule that does not depend on being allowed, we will only call transferFrom style: we will make addrFrom approve this test contract then invoke c.transferFrom(addrFrom, addrTo, tAmount). But transferFrom uses same internal _transfer which enforces allowedRoles. So to ensure not reverting we require that either addrFrom or addrTo equals address(this). That way one side is this contract which previously transferred tokens and may be in allowed roles; to be conservative, require addrFrom == address(this) || addrTo == address(this).
        require(addrFrom == address(this) || addrTo == address(this), "one party must be this contract to pass allowed-role check");

        // Read txReward before
        uint256 beforeFromReward = c.txReward(addrFrom);
        uint256 beforeToReward = c.txReward(addrTo);

        // Perform the transfer: if this contract is sender use c.transfer, else instruct the test contract to transferFrom by first approving
        bool reverted = false;
        if (addrFrom == address(this)) {
            // send from this contract to addrTo
            try c.transfer(addrTo, tAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else if (addrTo == address(this)) {
            // send from addrFrom to this contract using transferFrom: first have addrFrom approve this contract
            // But we cannot make addrFrom call approve since we don't control it. To avoid this, require addrFrom == address(this) above; so this branch won't run.
            reverted = true; // unreachable placeholder
        }

        // Read txReward after
        uint256 afterFromReward = c.txReward(addrFrom);
        uint256 afterToReward = c.txReward(addrTo);

        // Determine which beneficiary should have gained reward according to contract logic:
        // If sender had allowed role (buy-role), recipient gets reward; else if recipient had allowed role (sell-role), sender gets reward.
        // We cannot observe allowedRoles, but since we ensured address(this) is one party and this contract performed the transfer as sender when addrFrom==address(this), the code path used is _allowedRoles[sender] true -> _tokenBuyTransferReward if sender allowed; else if recipient allowed -> _tokenSellTransferReward; else plain transfer with no reward.
        // To be conservative and make a general rule: if afterToReward > beforeToReward then the increment must equal expectedReward; similarly if afterFromReward > beforeFromReward then increment equals expectedReward. And if neither increased then either tAmount < minTxn or contract lacked balance or allowed-role conditions didn't trigger.

        // Assert the general rule:
        bool toIncreased = afterToReward > beforeToReward;
        bool fromIncreased = afterFromReward > beforeFromReward;

        // If a reward was recorded for either party, it must equal expectedReward (computed using public minTxnAmount, rewardRate, percent) AND the transfer must not have reverted.
        assert( (!reverted) && ( (toIncreased == true ? (afterToReward - beforeToReward == expectedReward) : true) && (fromIncreased == true ? (afterFromReward - beforeFromReward == expectedReward) : true) ) );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // addrTo: recipient of a transfer from this contract
    // tAmount: token amount to transfer (in raw token units, matching C.decimals)
    // contractRewardBalance: amount to deposit into c so it may pay rewards
    function run(address addrTo, uint256 tAmount, uint256 contractRewardBalance) public payable {
        require(addrTo != address(0), "nonzero recipient");
        // Ensure this contract has tokens to send: the deployed C minted initial supply to the deployer (this test deployed c), so this contract holds tokens.

        // Read public parameters used to compute expected reward
        uint256 minTxn = c.minTxnAmount();
        uint256 rewardRate = c.rewardRate();
        uint256 pct = c.percent();

        // Compute expected reward according to public formula (all public view calls)
        uint256 expectedReward = 0;
        if (tAmount >= minTxn) {
            expectedReward = (tAmount * rewardRate) / pct;
        }

        // Top-level state-changing calls on c only, flat structure as required.
        // 1) Transfer some tokens from this contract to the token contract address (to top-up its reward pool) if requested
        if (contractRewardBalance > 0) {
            c.transfer(address(c), contractRewardBalance);
        }

        // 2) Record txReward before
        uint256 beforeTo = c.txReward(addrTo);
        uint256 beforeThis = c.txReward(address(this));

        // 3) Perform the transfer from this contract to addrTo and capture whether it reverted via try/catch
        bool reverted;
        try c.transfer(addrTo, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // 4) Read txReward after
        uint256 afterTo = c.txReward(addrTo);
        uint256 afterThis = c.txReward(address(this));

        // Exactly one assert stating the general rule:
        // If either txReward increased for addrTo or for this contract, then the increase equals expectedReward and the transfer did not revert.
        // (If no increase occurred, no constraint beyond non-negativity is required.)
        assert(
            (
                (afterTo >= beforeTo) && (afterThis >= beforeThis) &&
                (
                    // if addrTo increased, it must equal expectedReward
                    (afterTo > beforeTo ? (afterTo - beforeTo == expectedReward) : true)
                ) &&
                (
                    // if this contract increased, it must equal expectedReward
                    (afterThis > beforeThis ? (afterThis - beforeThis == expectedReward) : true)
                ) &&
                // Any observed increase implies the transfer did not revert
                ( (afterTo > beforeTo || afterThis > beforeThis) ? (reverted == false) : true )
            )
        );
    }

    receive() external payable { }
}

