contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry exercising transferFrom/transfer and checking balances update consistency
    // Parameters: sender (from), recipient (to), amount, useApprove flag to choose transfer path
    function run(address sender, address recipient, uint256 amount, bool useTransferFrom) public payable {
        require(sender != address(0) && recipient != address(0));
        // read balances before
        uint256 beforeSender = c.balanceOf(sender);
        uint256 beforeRecipient = c.balanceOf(recipient);

        bool reverted = false;
        // If invoking transferFrom path, we must have allowance; as this test contract is the deployer of c,
        // we cannot set allowance on behalf of arbitrary sender. So only call transferFrom when sender == address(this)
        if(useTransferFrom) {
            // require precondition that makes transferFrom plausible
            require(sender == address(this));
            // approve recipient as spender of this contract's tokens
            // Note: approve is a state-changing call and must be top-level.
            c.approve(recipient, amount);
            // now try transferFrom from this -> recipient by recipient as msg.sender
            // We can't make the call originate from recipient in this context (msg.sender will be this contract)
            // so instead we attempt transferFrom with this contract as caller (allowed since allowance set to recipient not this),
            // which may revert — we capture revert.
            try c.transferFrom(sender, recipient, amount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // call transfer from this contract (msg.sender == this contract) transferring tokens from this contract to recipient
            // This requires that sender == address(this)
            if(sender == address(this)) {
                try c.transfer(recipient, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            } else {
                // We cannot initiate a transfer from other arbitrary sender addresses (we are not them).
                // In this branch we instead attempt to call transfer from sender to recipient using transferFrom,
                // but that requires allowance; attempt and capture revert.
                try c.transferFrom(sender, recipient, amount) {
                    reverted = false;
                } catch {
                    reverted = true;
                }
            }
        }

        // read balances after
        uint256 afterSender = c.balanceOf(sender);
        uint256 afterRecipient = c.balanceOf(recipient);

        // General property asserted: if the call did not revert then recipient's balance increased by exactly amount
        // and sender's balance decreased by at least amount (since reflections could complicate exact equality for sender,
        // but recipient must receive the nominal tAmount on non-reverted successful transfers as per Transfer emits)
        assert(reverted || (afterRecipient == beforeRecipient + amount && afterSender + amount <= beforeSender));
    }

    receive() external payable {}
}

