contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try transferring from this contract (which will be msg.sender for calls to c).
    // Inputs: recipient address encoded as uint160 and transfer amount.
    function run(uint160 recipientUint, uint256 tAmount) public payable {
        address recipient = address(recipientUint);
        // avoid trivial zero-address and zero-amount to get meaningful behavior
        require(recipient != address(0) && tAmount > 0, "pre");

        // observe before-values via public getters
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(address(this));

        // make the state-changing call and record if it reverted
        bool reverted;
        try c.transfer(recipient, tAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(address(this));

        // General invariant: if the transfer did not revert then totalSupply is unchanged
        // and the sender's observable balance did not decrease by more than tAmount.
        // Written to avoid underflow: balSenderAfter + tAmount >= balSenderBefore
        assert(reverted || (totalAfter == totalBefore && balSenderAfter + tAmount >= balSenderBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single entry point: try arbitrary transfer between two addresses with amount
    function run(address sender, address recipient, uint256 amount) public payable {
        require(sender != address(0) && recipient != address(0));

        // Read some pre-call observables
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 txRewardSenderBefore = c.txReward(sender);
        uint256 txRewardRecipientBefore = c.txReward(recipient);

        // We will attempt transferFrom(sender, recipient, amount) as this contract is the caller
        // First, try to use approve to set allowance so transferFrom can proceed if allowed
        // Approve may revert if called from wrong address, but we are msg.sender here and only public functions of c are used.
        bool revertedTransfer;
        try c.transferFrom(sender, recipient, amount) {
            revertedTransfer = false;
        } catch {
            revertedTransfer = true;
        }

        // Read post-call observables
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 txRewardSenderAfter = c.txReward(sender);
        uint256 txRewardRecipientAfter = c.txReward(recipient);

        // General rule expressed as a single assert:
        // If the transfer reverted, then balances and rewards must be unchanged; otherwise totalSupply unchanged and
        // balances must reflect a conservation (sender decreased by amount and recipient increased by amount) and
        // txReward for either party can only increase (not decrease), and increases are bounded by reward logic: they cannot exceed amount.
        assert(
            // if reverted => no changes
            (revertedTransfer &&
                totalBefore == totalAfter &&
                balSenderBefore == balSenderAfter &&
                balRecipientBefore == balRecipientAfter &&
                txRewardSenderBefore == txRewardSenderAfter &&
                txRewardRecipientBefore == txRewardRecipientAfter)
            ||
            // else (succeeded) => totalSupply preserved and simple conservation of token amounts (observed via balanceOf)
            (!revertedTransfer &&
                totalBefore == totalAfter &&
                // sender balance decreases by at most amount (some internal fees/logic could alter distribution, but net effect should not create tokens)
                balSenderAfter + amount >= balSenderBefore &&
                // recipient balance increases by at most amount (same reasoning)
                balRecipientBefore + amount >= balRecipientAfter &&
                // total change equals transfer delta: (sender decrease) == (recipient increase) when comparing token units observed
                (balSenderBefore - balSenderAfter) == (balRecipientAfter - balRecipientBefore) &&
                // txReward values never decrease
                txRewardSenderAfter >= txRewardSenderBefore &&
                txRewardRecipientAfter >= txRewardRecipientBefore &&
                // any reward increase for either side cannot exceed the transfer amount
                (txRewardSenderAfter - txRewardSenderBefore) <= amount &&
                (txRewardRecipientAfter - txRewardRecipientBefore) <= amount
            )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Try arbitrary transferFrom between two addresses with amount
    function run(address sender, address recipient, uint256 amount) public payable {
        // basic preconditions to avoid zero-address trivial reverts
        require(sender != address(0) && recipient != address(0));

        // Read pre-call observables
        uint256 totalBefore = c.totalSupply();
        uint256 balSenderBefore = c.balanceOf(sender);
        uint256 balRecipientBefore = c.balanceOf(recipient);
        uint256 txRewardSenderBefore = c.txReward(sender);
        uint256 txRewardRecipientBefore = c.txReward(recipient);

        // Attempt the state-changing call and capture whether it reverted
        bool revertedTransfer;
        try c.transferFrom(sender, recipient, amount) {
            revertedTransfer = false;
        } catch {
            revertedTransfer = true;
        }

        // Read post-call observables
        uint256 totalAfter = c.totalSupply();
        uint256 balSenderAfter = c.balanceOf(sender);
        uint256 balRecipientAfter = c.balanceOf(recipient);
        uint256 txRewardSenderAfter = c.txReward(sender);
        uint256 txRewardRecipientAfter = c.txReward(recipient);

        // Assert the general rule as a single assertion
        assert(
            // If the call reverted -> nothing observable changed
            (revertedTransfer &&
                totalBefore == totalAfter &&
                balSenderBefore == balSenderAfter &&
                balRecipientBefore == balRecipientAfter &&
                txRewardSenderBefore == txRewardSenderAfter &&
                txRewardRecipientBefore == txRewardRecipientAfter)
            ||
            // Otherwise the call succeeded -> totalSupply unchanged and token change conserved and rewards monotonic and bounded
            (!revertedTransfer &&
                totalBefore == totalAfter &&
                // conservation: decrease of sender equals increase of recipient (observed via balanceOf)
                (balSenderBefore >= balSenderAfter) &&
                (balRecipientAfter >= balRecipientBefore) &&
                (balSenderBefore - balSenderAfter) == (balRecipientAfter - balRecipientBefore) &&
                // txReward never decreases
                txRewardSenderAfter >= txRewardSenderBefore &&
                txRewardRecipientAfter >= txRewardRecipientBefore &&
                // any increase in txReward for either party is no more than the nominal transfer amount
                (txRewardSenderAfter - txRewardSenderBefore) <= amount &&
                (txRewardRecipientAfter - txRewardRecipientBefore) <= amount
            )
        );
    }

    receive() external payable {}
}
